\begin{lemma}[gluing]\label{U:lem:glue}
If $a,b>0$, $\Phi_1$ is an \fn{IsFlow} on $[0,a]$, $\Phi_2$ is an \fn{IsFlow} on $[0,b]$ and $\Phi_2(0)=\Phi_1(a)$, then $\Phi(t)=\Phi_1(t)$ ($t\le a$), $\Phi_2(t-a)$ ($t\ge a$) is an \fn{IsFlow} on $[0,a+b]$.
\end{lemma}
\begin{proof}\LeanSthree\ (GE) \fn{CWFlow.Curve.isFlow_glue_endpoint} (a $\Psi$ equal to $\Phi_1$ on $[0,a]$ and to $\Phi_2(\cdot-a)$ on $[a,a+b]$, i.e.\ $\Psi=\Phi$ on $[0,a+b]$; the clauses of \fn{IsFlow} on $[0,a+b]$ involve only the values on $[0,a+b]$). The overlap form is (Gl) \fn{rst_glue}. (Text v42: text v41 had a hand proof. Lemma~\ref{U:lem:max} no longer needs gluing: it takes maximality from (T1).)
\end{proof}

\begin{lemma}[maximal smooth solution]\label{U:lem:max}
Let $F=\gamma(t_1)$. There is $T_{\max}\in(0,\infty]$ and a unique $\Phi:[0,T_{\max})\times\mathbb S^1\to\mathbb C$ such that $\Phi|_{[0,T]}$ is an \fn{IsFlow} with $\Phi(0)=F$ for every $T<T_{\max}$, and there is no \fn{IsFlow} on $[0,T_{\max}]$ with $\Phi(0)=F$ when $T_{\max}<\infty$. Every \fn{IsFlow} on $[0,T]$ from $F$ is the restriction of $\Phi$. Put $\gamma(t_1+t):=\Phi(t)$.
\end{lemma}
\begin{proof}\tL\ (text v42). $F=\gamma(t_1)$ is the value at $t_1$ of an \fn{IsFlow} on an interval $[0,T]\ni t_1$ (Theorem C-1 (i), (iv) of \fn{C1_identification_v42.tex}), so it is an \fn{IsLagImmersion E1 Jc} by the immersion clause of \fn{IsFlow}; no conversion from a periodic curve is needed here. (T1) with $F_0=F$ gives $T_{\max}$ and $\Phi$. Clause (i) is ``$\Phi|_{[0,T]}$ is an \fn{IsFlow} for every $T<T_{\max}$''. Clause (ii) gives that every \fn{IsFlow} from $F$ on $[0,T]$ has $T<T_{\max}$ and is the restriction of $\Phi$; in particular there is none on $[0,T_{\max}]$ when $T_{\max}<\infty$, and $\Phi$ is unique on $[0,T_{\max})$. (Text v41 assembled this by hand from (L1), (L2) and the gluing lemma.)
\end{proof}

\begin{lemma}[symmetry]\label{U:lem:sym}
$\sigma\circ\gamma(t)=\gamma(t)\circ\iota$ for all $t\in[t_1,t_1+T_{\max})$.
\end{lemma}
\begin{proof}\tL\ (text v42). (Sy) \fn{cdf_symmetric}, applied to $\Phi|_{[0,T]}$ for each $T<T_{\max}$; its hypothesis $\overline{\Phi(0,p^{-1})}=\Phi(0,p)$ is (S4.2) with $\iota(p)=p^{-1}=\bar p$ on \fn{Circle}, and its conclusion $\overline{\Phi(t,p^{-1})}=\Phi(t,p)$ for all $p$ is the claim (replace $p$ by $p^{-1}$). (Text v41 had a hand proof through S2, S3; the closure of \fn{IsFlow} under $\sigma\circ\cdot\circ\iota$ is now the Lean lemma \fn{IsFlow.conj_reflect}.)
\end{proof}

\begin{lemma}[blow-up criterion, the form needed]\label{U:lem:bu}
If $T_{\max}<\infty$ then $\sup_{t<t_1+T_{\max}}\int_{\gamma(t)}k^2ds=\infty$.
\end{lemma}
\begin{proof}\tL\ (text v42). Clause (iii) of (T1): if $T_{\max}<\infty$, then $\fn{bendingEnergy}(\fn{lift}(\Phi(t)))$ is unbounded on $[0,T_{\max})$, and this quantity is $\int_{\gamma(t_1+t)}k^2ds$ (\S\ref{U:sec:lean}, last paragraph before Lemma~\ref{U:lem:vel}). (Texts v40, v41 derived this from the statement of DKS Theorem~3.1, with the author item A-2 on ``maximal solution''; neither is used now.)
\end{proof}
\begin{remark}[extension form; (D1) replaced]\label{U:rem:D1}
The extension form of the criterion is (T2) \fn{cdf_extends_of_bounded_energy} \tL: if $\int k^2ds$ stays bounded near a finite end, the flow extends to an \fn{IsFlow} on a closed interval beyond it, so the extension is an immersion at the end time and satisfies the velocity identity there (the ``C-4 completion'' that text v41 added to DKS (D1) by hand is part of the Lean statement). (T1) is proved from (T2) in Lean; nothing in U-1 uses (T2) directly.
\end{remark}
\noindent This is (P1$'$), with existence, uniqueness, maximality, symmetry and the criterion from the compiled Lean theorems (T1), (Sy) (and (L1), (L2)) \tL, subject to the build and commit items of \S\ref{U:sec:gaps} (text v42; text v41: (L1), (L2) read from source and DKS (D2)).

